```
count[0], count[1] = tally of student preferences
for each sandwich s in stack order:
    if count[s] > 0:
        count[s] -= 1
    else:
        break
return count[0] + count[1]
```

code.cpp:
class Solution {
public:
    int countStudents(vector<int>& students, vector<int>& sandwiches) {
        int cnt[2] = {0, 0};
        for (int s : students) cnt[s]++;
        for (int sand : sandwiches) {
            if (cnt[sand] > 0) cnt[sand]--;
            else break;
        }
        return cnt[0] + cnt[1];
    }
};
